package in.kalaimarket;
import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
import java.util.*;import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.*;
class PublicSignalServiceTest {
 final ObjectMapper json=new ObjectMapper();final PublicMarketRepository market=mock(PublicMarketRepository.class);final AutoSignalRepository signals=mock(AutoSignalRepository.class);final ScanStateRepository scans=mock(ScanStateRepository.class);final FeedLockRepository locks=mock(FeedLockRepository.class);final MarketQuoteRepository quotes=mock(MarketQuoteRepository.class);final V28Engine engine=new V28Engine(json);
 final PublicSignalService service=new PublicSignalService(engine,market,signals,scans,locks,quotes,new SignalStrategy(),json,true,false);
 @BeforeEach void setup(){when(locks.lock(anyString())).thenReturn(Optional.of(new WatchItem("BTCUSD")));when(signals.findBySymbolAndStatusIn(anyString(),any())).thenReturn(List.of());}
 @AfterEach void close(){engine.close();}
 @Test void storesSignalAndReferenceQuoteWithoutAnyMt5Feed()throws Exception{service.ingest(V28EngineTest.fixture(json));verify(signals).save(argThat(s->s.strategy.equals("KMR_V28_PUBLIC")&&s.pendingKind==AutoSignal.PendingKind.MARKET&&s.quality==98&&s.decisionContext.containsKey("scan")&&s.decisionContext.containsKey("evaluatedAt")&&s.decisionContext.get("scan") instanceof Map<?,?> evidence&&evidence.containsKey("e20")&&evidence.containsKey("gates")));verify(quotes).save(argThat(q->q.source.equals("PUBLIC_REFERENCE")));verify(market).save(any());}
 @Test void sameClosedBarNotInsertedTwice()throws Exception{when(signals.existsBySymbolAndTimeframeAndSourceBar(anyString(),any(),any())).thenReturn(true);service.ingest(V28EngineTest.fixture(json));verify(signals,never()).save(any());}
 @Test void existingPublicSetupBlocksAnother()throws Exception{var s=new AutoSignal();s.strategy="KMR_V28_PUBLIC";s.timeframe=Timeframe.M15;s.tp1=AutoSignal.price(2100);s.tp2=AutoSignal.price(2200);s.lastQuoteAt=java.time.Instant.now().plusSeconds(10);when(signals.findBySymbolAndStatusIn(anyString(),any())).thenReturn(List.of(s));service.ingest(V28EngineTest.fixture(json));verify(signals,never()).save(any());}
 @Test void mt5IngestIsExecutionOnlyInIndependentMode(){var quotes=mock(MarketQuoteRepository.class);var strategy=mock(SignalStrategy.class);var svc=new AutoSignalService(locks,signals,scans,strategy,quotes,true);var n=java.time.Instant.now();var bars=new ArrayList<FeedRequest.Candle>();for(int i=0;i<220;i++)bars.add(new FeedRequest.Candle(n.minusSeconds(60L*(221-i)),n.minusSeconds(60L*(220-i)),2000,2001,1999,2000));assertEquals("EXECUTION_ONLY",svc.ingest(new FeedRequest("XAUUSD",Timeframe.M1,new FeedRequest.Quote(n,2000,2000.1),bars)).get("status"));verify(strategy,never()).analyze(any(),any());verify(quotes,never()).save(any());}
}
